package com.mycompany.rentalmanagement.servlet;import com.mycompany.rentalmanagement.dao.RentalDAO;import com.mycompany.rentalmanagement.util.ValidationUtil;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet("/returns") public class ReturnServlet extends HttpServlet{RentalDAO dao=new RentalDAO();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{r.setAttribute("rentals",dao.list());r.getRequestDispatcher("/WEB-INF/views/returns.jsp").forward(r,s);}catch(Exception e){r.setAttribute("error",e.getMessage());r.getRequestDispatcher("/WEB-INF/views/error.jsp").forward(r,s);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{dao.returnVehicle(Long.parseLong(r.getParameter("rental_id")),ValidationUtil.date(r.getParameter("actual_return_date"),"Return date"));s.sendRedirect(r.getContextPath()+"/returns?success=1");}catch(Exception e){r.setAttribute("error",e.getMessage());doGet(r,s);}}}
